CREATE TABLE IF NOT EXISTS `User` (`userId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `firstName` TEXT NOT NULL, `lastName` TEXT NOT NULL, `birthDate` TEXT NOT NULL, `weight` REAL NOT NULL, `height` REAL NOT NULL, `bmi` REAL NOT NULL);
CREATE TABLE IF NOT EXISTS `events` (`eventId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `userId` INTEGER NOT NULL, `eventName` TEXT NOT NULL, `eventDate` TEXT NOT NULL, `artOfSport` TEXT NOT NULL, `comment` TEXT NOT NULL, `sessionId` TEXT, `isUploaded` INTEGER NOT NULL, `uploadedAt` INTEGER, `startCity` TEXT, `startCountry` TEXT, `endCity` TEXT, `endCountry` TEXT, `startAddress` TEXT, `endAddress` TEXT, `eventSource` TEXT, `sportFamily` TEXT, `discipline` TEXT, `eventFormat` TEXT, FOREIGN KEY(`userId`) REFERENCES `User`(`userId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `metrics` (`metricId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `heartRate` INTEGER NOT NULL, `heartRateDevice` TEXT NOT NULL, `speed` REAL NOT NULL, `distance` REAL NOT NULL, `cadence` INTEGER, `lap` INTEGER NOT NULL, `timeInMilliseconds` INTEGER NOT NULL, `unity` TEXT NOT NULL, `elevation` REAL NOT NULL, `elevationGain` REAL NOT NULL, `elevationLoss` REAL NOT NULL, `slope` REAL NOT NULL, `steps` INTEGER, `strideLength` REAL, `temperature` REAL, `accuracy` REAL, `pressure` REAL, `pressureAccuracy` INTEGER, `altitudeFromPressure` REAL, `seaLevelPressure` REAL, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `locations` (`locationId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `latitude` REAL NOT NULL, `longitude` REAL NOT NULL, `altitude` REAL NOT NULL, `backyardLap` INTEGER NOT NULL, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `weather` (`weatherId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `weatherRestApi` TEXT NOT NULL, `temperature` REAL NOT NULL, `windSpeed` REAL NOT NULL, `windDirection` TEXT NOT NULL, `relativeHumidity` INTEGER NOT NULL, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `device_status` (`deviceStatusId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `numberOfSatellites` TEXT NOT NULL, `sensorAccuracy` TEXT NOT NULL, `signalStrength` TEXT NOT NULL, `batteryLevel` TEXT NOT NULL, `connectionStatus` TEXT NOT NULL, `sessionId` TEXT NOT NULL, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `current_recording` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sessionId` TEXT NOT NULL, `eventId` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL, `latitude` REAL NOT NULL, `longitude` REAL NOT NULL, `altitude` REAL NOT NULL, `speed` REAL NOT NULL, `distance` REAL NOT NULL, `lap` INTEGER NOT NULL, `currentLapDistance` REAL NOT NULL, `movementDuration` TEXT NOT NULL, `inactivityDuration` TEXT NOT NULL, `movementStateJson` TEXT NOT NULL, `lazyStateJson` TEXT NOT NULL, `startDateTimeEpoch` INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS `index_current_recording_sessionId` ON `current_recording` (`sessionId`);
CREATE TABLE IF NOT EXISTS `lap_times` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sessionId` TEXT NOT NULL, `eventId` INTEGER NOT NULL, `lapNumber` INTEGER NOT NULL, `startTime` INTEGER NOT NULL, `endTime` INTEGER NOT NULL, `distance` REAL NOT NULL);
CREATE INDEX IF NOT EXISTS `index_lap_times_sessionId` ON `lap_times` (`sessionId`);
CREATE INDEX IF NOT EXISTS `index_lap_times_eventId` ON `lap_times` (`eventId`);
CREATE TABLE IF NOT EXISTS `planned_events` (`plannedEventId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `userId` INTEGER NOT NULL, `plannedEventName` TEXT NOT NULL, `plannedEventDate` TEXT NOT NULL, `plannedEventEndDate` TEXT NOT NULL, `plannedEventType` TEXT NOT NULL, `plannedEventCountry` TEXT NOT NULL, `plannedEventCity` TEXT NOT NULL, `plannedLatitude` REAL, `plannedLongitude` REAL, `isEnteredAndFinished` INTEGER NOT NULL, `website` TEXT NOT NULL, `comment` TEXT NOT NULL, `reminderDateTime` TEXT NOT NULL, `isReminderActive` INTEGER NOT NULL, `isRecurring` INTEGER NOT NULL, `recurringType` TEXT NOT NULL, `recurringInterval` INTEGER NOT NULL, `recurringEndDate` TEXT NOT NULL, `recurringDaysOfWeek` TEXT NOT NULL, FOREIGN KEY(`userId`) REFERENCES `User`(`userId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `clothing` (`clothingId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `clothing` TEXT NOT NULL, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `wheel_sprocket` (`wheelId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `wheelSize` REAL, `sprocket` INTEGER, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `network` (`networkId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `websocketIpAddress` TEXT NOT NULL, `restApiAddress` TEXT NOT NULL, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `waypoints` (`waypointId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `latitude` REAL NOT NULL, `longitude` REAL NOT NULL, `name` TEXT NOT NULL, `description` TEXT, `elevation` REAL, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_waypoints_eventId` ON `waypoints` (`eventId`);
CREATE TABLE IF NOT EXISTS `event_media` (`mediaId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `mediaUuid` TEXT NOT NULL, `mediaType` TEXT NOT NULL, `fileExtension` TEXT NOT NULL, `thumbnailUrl` TEXT, `fullUrl` TEXT, `localThumbnailPath` TEXT, `caption` TEXT, `sortOrder` INTEGER NOT NULL, `isUploaded` INTEGER NOT NULL, `localFilePath` TEXT, `fileSizeBytes` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, FOREIGN KEY(`eventId`) REFERENCES `events`(`eventId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_event_media_eventId` ON `event_media` (`eventId`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_event_media_mediaUuid` ON `event_media` (`mediaUuid`);
CREATE TABLE IF NOT EXISTS `discipline_transitions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `eventId` INTEGER NOT NULL, `sessionId` TEXT NOT NULL, `disciplineName` TEXT NOT NULL, `transitionNumber` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS `index_discipline_transitions_eventId` ON `discipline_transitions` (`eventId`);
CREATE INDEX IF NOT EXISTS `index_discipline_transitions_sessionId` ON `discipline_transitions` (`sessionId`);
CREATE TABLE IF NOT EXISTS `waypoint_photos` (`photoId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `waypointId` INTEGER NOT NULL, `photoPath` TEXT NOT NULL, FOREIGN KEY(`waypointId`) REFERENCES `waypoints`(`waypointId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_waypoint_photos_waypointId` ON `waypoint_photos` (`waypointId`);
